  ('346392cd-8ba1-4cd0-a19b-3142e0ab8827', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई सोच रही थीं कि उन््हें देखते ही मिट्ठू ‘रामम रामम सीतारामम’ की रट लगाकर आसममान सिर पर उठा लेगा, पिंजड़़े मेें कूद-फाँद ममचाकर तूफान खड़़ा कर देगा, लेकिन वहाँ बैठे एवजी मिट्ठू ने उन््हें देखकर कोई हरकत नहीं की, वह केवल इधर-उधर ताकता रहा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('31d12556-b8d4-4af6-ab27-150139538f60', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई अपने मिट्ठू को गुहार कर थक गर्इं लेकिन उनके सूनेपन का साथी न जाने किन अममराइयोों मेें घूमम रहा होगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
