  ('84fa415e-287b-4c88-800f-b34ccf129d2c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई अपने मिट्ठू को गुहार कर थक गर्इं लेकिन उनके सूनेपन का साथी न जाने किन अममराइयोों मेें घूमम रहा होगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('65dbbae4-f1e3-41d3-8202-e0bfa11d5054', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रामम रामम, सीतारामम बोलते-बोलते उनका गला सूख जाता, ममास्टराइन भोजन ठंडा होने की शिकाययत करतीं, तो आग््नेयय दृष््‍टटि से उनकी ओर देखकर पानी पीकर फिर दुहराते — रामम रामम सीतारामम, हर गंगे... फिर खीझकर कहते— ममर जा! ममर जा!! पर वह पिंजरे के अंदर से टुकुर-टुकुर उन््हें देखता रहता यया शाययद उनकी बेवकूफी पर हँसता रहता हो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
