  ('f7708202-1758-4243-b720-237709b2f8c1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन वहाँ बैठे एवजी मिट्ठू ने उन््हें देखकर कोई हरकत नहीं की, वह केवल इधर-उधर ताकता रहा। ताई अपने मिट्ठू को गुहार कर थक गर्इं लेकिन उनके सूनेपन का साथी न जाने किन अममराइयोों मेें घूमम रहा होगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f962bad1-4609-4dd4-bc46-6f1685ac300b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गहरी साँस लेकर ताई कहतीं, “भगवान! कैसे नैयया पार लगेगी?” और बंद पिंजड़़े मेें अपने पंखों को फड़फड़़ाता, उछल-कूद ममचाता मिट्ठू उत्तर देता, “रामम-रामम कहो, सीतारामम कहो।” ताई दुहरातीं— सीतारामम! सीतारामम! ताई और मिट्ठू, मिट्ठू और ताई। अब यये ही दो प्राणी गाँव के बीच मेें स््थथित बड़़े घर के उस सूने खंडहर मेें एक-दूसरे को सहारा देने के लिए रह गए थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('218a833e-6595-42fe-9811-1dd6250a1da1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई ने अपने जीवन मेें अच्छे दिन भी देखे थे। पूत-परिवार, बहू-बेटिययाँ, नौकर-चाकर, गायय-ढोर, क््या नहीं था बड़़े घर मेें! देखते ही देखते क््या से क््या हो गयया! बहू-बेटे गाँव का ममोह छोड़कर शहरों के होकर रह गए। बेटिययाँ अपने-अपने हाथ पीले कराकर अपनी गृहस्थी मेें रमम गइ«, किसके भरोसे कारबार संभलता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e8208ab1-d14c-44ae-aefa-d760ad1ef3dd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$धीरे-धीरे सब पराए हाथों मेें चला गयया। जब खेती-बाड़़ी नहीं, कारबार नहीं, तो नौकर-चाकर किस दमम पर टिकते! अपनी अकेली जान के लिए ताई दो जून का एक जून चूल्हा फूँक लेतीं, व्रत-उपवास के बहाने चौका-चूल्हा टाल जातीं, पेट की सममस््या उनके लिए कभी सममस््या नहीं रही, पर सूने घर की भाँयय-भाँयय जैसे उन््हें काटने को दौड़ती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5e4d7ab7-de65-4fc6-a233-c49675335840', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भला हो गनपत का, जिसने ताई के सूनेपन को सहारा दे दियया था, वह न जाने कहाँ से एक प््यारा-सा पहाड़़ी तोता ले आयया था। ताई की सारी मममता मिट्ठू पर बरस पड़़ी। वह रात-दिन मिट्ठू को लेकर ही बेचैन रहने लगीीं। जो ताई अपनी खातिर चूल्हा जलाने मेें आलस््य कर जाती थीं, वही अब नियममपूर््वक मिट्ठू के लिए दाल-भात बनातीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5d8e8bf7-05e2-4ef6-b146-342ec36e6af1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मिट्ठू के वक्त-बेवक्त के तकाजों के लिए रोटी बचाकर रखतीं। अब ताई को इस बात की पूरी जानकारी रहने लगी थी कि किसके खेत मेें हरी मिर्चचें तैययार हो गई हैं और किस पेड़ मेें फसल के आखिरी अममरूद बचे हैं। कुशाग्र बुद्धि छात्र की तरह मिट्ठू ताई के पढ़ाए पाठ को न केवल हू-ब-हू दुहरा देता बल््ककि एक-दो बार सुनकर ययाद भी रख लेता था और ममौके बे-ममौके ताई के सवालों का सटीक उत्तर दे देता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('06076dae-43ef-4547-bc55-86a7a609cb63', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बड़़े घर का सूनापन धीरे-धीरे मिट्ठू की बातचीत से अब रौनक मेें बदल गयया था, अड़ोस-पड़ोस की बहू-बेटिययाँ बच््चों को गोदी मेें उठाकर मिट्ठू से उनका ममन बहलाने के लिए आ जुटतीं और घर गुलजार हो जाता। सुबह पौ फटने लगती, पेड़ों मेें चिड़़िययाँ चहचहातीं संवादहीन संवादहीन$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a0c58d03-35b0-4e22-a76a-6e6f038ea1f9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गहरी साँस लेकर ताई कहतीं, “भगवान! कैसे नैयया पार लगेगी?” और बंद पिंजड़़े मेें अपने पंखों को फड़फड़़ाता, उछल-कूद ममचाता मिट्ठू उत्तर देता, “रामम-रामम कहो, सीतारामम कहो।” ताई दुहरातीं— सीतारामम! सीतारामम! ताई और मिट्ठू, मिट्ठू और ताई। अब यये ही दो प्राणी गाँव के बीच मेें स््थथित बड़़े घर के उस सूने खंडहर मेें एक-दूसरे को सहारा देने के लिए रह गए थे। ताई ने अपने जीवन मेें अच्छे दिन भी देखे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('298e81a0-1ea4-4f33-9018-7425ea728af7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पूत-परिवार, बहू-बेटिययाँ, नौकर-चाकर, गायय-ढोर, क््या नहीं था बड़़े घर मेें! देखते ही देखते क््या से क््या हो गयया! बहू-बेटे गाँव का ममोह छोड़कर शहरों के होकर रह गए। बेटिययाँ अपने-अपने हाथ पीले कराकर अपनी गृहस्थी मेें रमम गइ«, किसके भरोसे कारबार संभलता। धीरे-धीरे सब पराए हाथों मेें चला गयया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a2254bd2-0400-464b-a809-9b32b65fe79a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब खेती-बाड़़ी नहीं, कारबार नहीं, तो नौकर-चाकर किस दमम पर टिकते! अपनी अकेली जान के लिए ताई दो जून का एक जून चूल्हा फूँक लेतीं, व्रत-उपवास के बहाने चौका-चूल्हा टाल जातीं, पेट की सममस््या उनके लिए कभी सममस््या नहीं रही, पर सूने घर की भाँयय-भाँयय जैसे उन््हें काटने को दौड़ती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('154cd3b7-18fd-4e1a-bc4a-c4176328c71e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भला हो गनपत का, जिसने ताई के सूनेपन को सहारा दे दियया था, वह न जाने कहाँ से एक प््यारा-सा पहाड़़ी तोता ले आयया था। ताई की सारी मममता मिट्ठू पर बरस पड़़ी। वह रात-दिन मिट्ठू को लेकर ही बेचैन रहने लगीीं। जो ताई अपनी खातिर चूल्हा जलाने मेें आलस््य कर जाती थीं, वही अब नियममपूर््वक मिट्ठू के लिए दाल-भात बनातीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
