  ('65fcb2d7-67ee-4c39-875c-a0f75426df93', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब खेती-बाड़़ी नहीं, कारबार नहीं, तो नौकर-चाकर किस दमम पर टिकते! अपनी अकेली जान के लिए ताई दो जून का एक जून चूल्हा फूँक लेतीं, व्रत-उपवास के बहाने चौका-चूल्हा टाल जातीं, पेट की सममस््या उनके लिए कभी सममस््या नहीं रही, पर सूने घर की भाँयय-भाँयय जैसे उन््हें काटने को दौड़ती थी। भला हो गनपत का, जिसने ताई के सूनेपन को सहारा दे दियया था, वह न जाने कहाँ से एक प््यारा-सा पहाड़़ी तोता ले आयया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b0ee9d5e-1a9f-442a-a687-36dad84fb10a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई की सारी मममता मिट्ठू पर बरस पड़़ी। वह रात-दिन मिट्ठू को लेकर ही बेचैन रहने लगीीं। जो ताई अपनी खातिर चूल्हा जलाने मेें आलस््य कर जाती थीं, वही अब नियममपूर््वक मिट्ठू के लिए दाल-भात बनातीं। मिट्ठू के वक्त-बेवक्त के तकाजों के लिए रोटी बचाकर रखतीं। अब ताई को इस बात की पूरी जानकारी रहने लगी थी कि किसके खेत मेें हरी मिर्चचें तैययार हो गई हैं और किस पेड़ मेें फसल के आखिरी अममरूद बचे हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ac5cb56b-5f53-4092-9403-ca7becdbf9a2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुशाग्र बुद्धि छात्र की तरह मिट्ठू ताई के पढ़ाए पाठ को न केवल हू-ब-हू दुहरा देता बल््ककि एक-दो बार सुनकर ययाद भी रख लेता था और ममौके बे-ममौके ताई के सवालों का सटीक उत्तर दे देता। बड़़े घर का सूनापन धीरे-धीरे मिट्ठू की बातचीत से अब रौनक मेें बदल गयया था, अड़ोस-पड़ोस की बहू-बेटिययाँ बच््चों को गोदी मेें उठाकर मिट्ठू से उनका ममन बहलाने के लिए आ जुटतीं और घर गुलजार हो जाता। सुबह पौ फटने लगती, पेड़ों मेें चिड़़िययाँ चहचहातीं संवादहीन संवादहीन$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('82425a98-b1fb-4bd2-a44d-afc81edf1650', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तो मिट्ठू भी जैसे ताई को भोर की झपकी से जगाने के लिए ही अपना पाठ शुरू कर देते— हर हर गंगे! हर हर गंगे!! सीतारामम बोल! सीतारामम बोल!! मिट्ठू रामम रामम! मिट्ठू रामम रामम!!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a15adc28-1e8d-460d-b19b-2be7bf2f121b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई अचकचाकर उठ बैठतीं। लाड़ से मिट्ठू को निहारकर आशीष देतीं— “जीते रहो बेटा, जुग-जुग जिओ” और मिट्ठू भी बदले मेें अपनी बुजुर्गी दिखाकर कहते— खुश रहो! खुश रहो!!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0b959be1-f85f-4f3d-a8ba-a90efb6c6b11', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई निहाल हो जातीं। वृद्धावस्था का शरीर और उस पर नई गृहस्थी का भार, कामम-काज से थककर ताई जब कभी पिंजरे को बगल मेें रखकर सुस्ताने लगतीीं तो अनाययास ही मिट्ठू से सवाल कर बैठतीं, “मिट्ठू! अब कैसे कटेगी?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('579fb02b-2b70-4283-9570-95596314cced', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और नौजवान मिट्ठू ताई के बुढ़ापे का सहारा बनकर दमम-खमम के साथ उन््हें दिलासा देते— कटेगी! कटेगी!! कटेगी!!!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6f6b329c-a476-493f-94c6-6388fceb5168', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई के थके शरीर मेें प्राण लौट आते, और तब उस अलस दोपहरी मेें ताई मिट्ठू को अपनी रामम-कहानी सुनाने लगतीीं। वैभव और सत्ता के बीते दिनों की गाथा। काल की अतल गहराइयोों से झाँकता एक-एक चेहरा ताई को नए-नए प्रसंगोों की ययाद दिला देता— जमीींदार$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
