  ('06ac9a0c-44bd-4ae7-a404-99775451c6a8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वृद्धावस्था का शरीर और उस पर नई गृहस्थी का भार, कामम-काज से थककर ताई जब कभी पिंजरे को बगल मेें रखकर सुस्ताने लगतीीं तो अनाययास ही मिट्ठू से सवाल कर बैठतीं, “मिट्ठू! अब कैसे कटेगी?”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4aa508ad-a8d4-4a57-8cd3-fa90da15c108', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई के थके शरीर मेें प्राण लौट आते, और तब उस अलस दोपहरी मेें ताई मिट्ठू को अपनी रामम-कहानी सुनाने लगतीीं। वैभव और सत्ता के बीते दिनों की गाथा। काल की अतल गहराइयोों से झाँकता एक-एक चेहरा ताई को नए-नए प्रसंगोों की ययाद दिला देता— जमीींदार$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dbbb1437-05ed-45aa-ad2f-7265c7ea20db', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$साहब का रोबीला चेहरा, उनके उपकारों से दबी प्रजा के अनगिनत चेहरे, वे हाथी, वे घोड़े, वे खेल-तममाशे, वे ब्याह-शादियाँ, तीज-त्योहार, जन्म और मृत्यु-पर्व, वे भोज, वे दावतें, जमींदार साहब के दरबार की रौनक, उनकी गुणग्राहकता, उनकी तुनकमिजाजी, उनका गुस्सा, उनके इशारे पर मर मिटने वाले लोग... ताई घंटों तक मिट्ठू को अपनी जीवन-गाथा सुनाती रहतीं और वह अपनी गर्दन टेढ़ी कर कभी धैर्यवान श्रोता बना रहता और कभी अपनी समझ के अनुसार बीच-बीच में कुछ टीका-टिप्पणी कर देता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('624731db-7ea7-4e3e-8a8c-dad2ec27043f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ऐसा नहीं कि ताई और मिट्ठू का संवाद हमेशा प्रेमपूर्ण ही रहता हो, कभी-कभी ताई थकी-मांदी लेटी होतीं और अपनी किसी जिद को मनवाने के लिए मिट्ठू पिंजड़े में तूफान खड़ा कर देते। पानी और दाने की कटोरियों को जान-बूझकर उलटा देते, तो खीझकर ताई कोसतीं, “मेरी जान खाने को आ गया है, मर जा!” और मिट्ठू भी उतनी ही खीझ के साथ हमला बोल देते, “मर जा! मर जा! मर जा!” फिर मान-मनौवल का दौर चलता और ताई और मिट्ठू की दुनिया पहले की तरह प्रेम से चलने लगती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5a735ea0-b759-48f6-a3fd-9e3626b51448', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई को घड़ी-भर के लिए भी मिट्ठू का वियोग सहन नहीं हो सकता था। कभी-कभार गाँव में थोड़ी देर के लिए भी न्यौते-बुलावे में जातीं, तो दस बार खिड़की-दरवाजों की साँकलें टोहकर देखतीं, कंजूस के धन की तरह मिट्ठू को छिपाकर रखतीं और जल्दी लौट आने का दिलासा देकर देहरी से पाँव बाहर निकालतीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b1669dc2-2280-4bdc-a58e-46ad828865ba', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन एक संयोग आ पड़ा कि ताई धर्म-संकट में पड़ गईं। इस लोक में ताई ने बहुत ऊँच-नीच देख लिए थे, अब कभी-कभी परलोक की चिंता भी मन में घर कर जाती। गाँव के कई लोग कुंभ-स्नान के लिए प्रयागराज जा रहे थे, अच्छा साथ बन रहा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0fae0cff-bef7-4f3a-92d5-49404896db06', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रयाग में कुंभ-स्नान का लोभ जहाँ उन्हें अपनी ओर खींच रहा था, वहीं मिट्ठू की चिंता अपनी ओर खींच रही थी। हँसी-हँसी में किसी ने सलाह दी, “ताई, मिट्ठू को भी साथ ले चलो, उसे भी गंगा-स्नान करा देना।” किसी दूसरे ने टोक दिया कि रेलगाड़ी में उसका भी टिकट लगेगा, आखिर वह भी तो बोलता-बतियाता प्राणी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dc0efe6a-f41e-4759-93b1-4cbd7c4f046d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई पशोपेश में पड़ गईं। टिकट का पैसा भी वह मिट्ठू की खातिर खर्च कर देतीं लेकिन मेले-ठेले, भीड़-भाड़ में उसकी सुरक्षा के बारे में उन्हें पूरा भरोसा नहीं था, अंत में जगन मास्टर की घरवाली ने उनकी चिंता दूर कर दी। वह ताई के लौटने तक मिट्ठू को अपने पास रखने के लिए सहमत हो गई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c6278ba8-5560-493e-8290-81bf6ca81f42', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विदा के दिन ताई की आँसुओं की धार रुके नहीं रुकती थी। बार-बार वह मिट्ठू को पुचकारतीं, जल्दी लौट आने का दिलासा देतीं। मिट्ठू भी उनकी बातों के उत्तर में ‘हर हर गंगे’, ‘राम राम सीताराम’ कहकर उन्हें भरोसा देते रहे कि वह जगन मास्टर की घरवाली के साथ प्रेम से रह लेंगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b3ebd5e5-4e2c-48c2-890c-1efb3b626749', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ताई तो कुंभ-स्नान के लिए चल दीं। लेकिन जगन मास्टर के घर में महाकुंभ हो गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
