  ('ecc8dcd4-3c24-47ad-b774-0732192ce323', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी-कभी ताई थकी-मांदी लेटी होतीं और अपनी किसी जिद को मनवाने के लिए मिट्ठू पिंजड़े में तूफान खड़ा कर देते। पानी और दाने की कटोरियों को जान-बूझकर उलटा देते, तो खीझकर ताई कोसतीं, “मेरी जान खाने को आ गया है, मर जा!”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
