  ('df39755e-552d-4d14-873e-b2378f1b136f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी-कभार गाँव में थोड़ी देर के लिए भी न्यौते-बुलावे में जातीं, तो दस बार खिड़की-दरवाजों की साँकलें टोहकर देखतीं, कंजूस के धन की तरह मिट्ठू को छिपाकर रखतीं और जल्दी लौट आने का दिलासा देकर देहरी से पाँव बाहर निकालतीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b5beef7b-30f2-4ba4-a07e-417cf8ec3d4e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस लोक में ताई ने बहुत ऊँच-नीच देख लिए थे, अब कभी-कभी परलोक की चिंता भी मन में घर कर जाती। गाँव के कई लोग कुंभ-स्नान के लिए प्रयागराज जा रहे थे, अच्छा साथ बन रहा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a235882c-c9e2-41cc-a7f8-b774b59d8dfe', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रयाग में कुंभ-स्नान का लोभ जहाँ उन्हें अपनी ओर खींच रहा था, वहीं मिट्ठू की चिंता अपनी ओर खींच रही थी। ताई पशोपेश में पड़ गईं। टिकट का पैसा भी वह मिट्ठू की खातिर खर्च कर देतीं लेकिन मेले-ठेले, भीड़-भाड़ में उसकी सुरक्षा के बारे में उन्हें पूरा भरोसा नहीं था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('fc92166a-5662-4731-a391-ac34836229e3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंत में जगन मास्टर की घरवाली ने उनकी चिंता दूर कर दी। वह ताई के लौटने तक मिट्ठू को अपने पास रखने के लिए सहमत हो गई थी। विदा के दिन ताई की आँसुओं की धार रुके नहीं रुकती थी। बार-बार वह मिट्ठू को पुचकारतीं, जल्दी लौट आने का दिलासा देतीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9f3c8189-d4fc-4569-bced-07cd0b367a58', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मिट्ठू भी उनकी बातों के उत्तर में ‘हर हर गंगे’, ‘राम राम सीताराम’ कहकर उन्हें भरोसा देते रहे कि वह जगन मास्टर की घरवाली के साथ प्रेम से रह लेंगे। ताई तो कुंभ-स्नान के लिए चल दीं। लेकिन जगन मास्टर के घर में महाकुंभ हो गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8dcce577-fae2-43eb-ab84-d9279adb6173', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रामम रामम, सीतारामम बोलते-बोलते उनका गला सूख जाता, ममास्टराइन भोजन ठंडा होने की शिकाययत करतीं, तो आग््नेयय दृष््‍टटि से उनकी ओर देखकर पानी पीकर फिर दुहराते — रामम रामम सीतारामम, हर गंगे...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8553874a-bbea-4df6-a887-c77ee6441ee3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '26188e0c-4ebd-4235-829b-d9ea0cded5bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर खीझकर कहते— ममर जा! ममर जा!! पर वह पिंजरे के अंदर से टुकुर-टुकुर उन््हें देखता रहता यया शाययद उनकी बेवकूफी पर हँसता रहता हो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-635Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
